import{_ as e,o as t,c as o,a2 as n}from"./chunks/framework.Do1fvF3d.js";const u=JSON.parse('{"title":"Personal data processing policy","description":"","frontmatter":{},"headers":[],"relativePath":"en/legal/politica-de-tratamiento.md","filePath":"en/legal/politica-de-tratamiento.md","lastUpdated":null}'),r={name:"en/legal/politica-de-tratamiento.md"};function i(s,a,l,d,c,p){return t(),o("div",null,[...a[0]||(a[0]=[n('<h1 id="personal-data-processing-policy" tabindex="-1">Personal data processing policy <a class="header-anchor" href="#personal-data-processing-policy" aria-label="Permalink to &quot;Personal data processing policy&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Draft</p><p>This document is a draft pending legal review. Highlighted details will be completed before launch. This English version is a courtesy translation; the <a href="/Tranqui/legal/politica-de-tratamiento">Spanish version</a> prevails.</p></div><p><strong>Version:</strong> 2026-10-03</p><p>This policy complies with Colombia&#39;s Law 1581 of 2012 and Decree 1377 of 2013 (compiled in Decree 1074 of 2015).</p><h2 id="_1-data-controller" tabindex="-1">1. Data controller <a class="header-anchor" href="#_1-data-controller" aria-label="Permalink to &quot;1. Data controller&quot;">​</a></h2><ul><li><strong>Name:</strong> <span class="placeholder">[CONTROLLER NAME]</span></li><li><strong>ID:</strong> <span class="placeholder">[ID OR TAX NUMBER]</span></li><li><strong>Address:</strong> <span class="placeholder">[CITY AND ADDRESS]</span></li><li><strong>Email for inquiries and complaints:</strong> <span class="placeholder">[CONTACT EMAIL]</span></li></ul><h2 id="_2-data-we-process-and-why" tabindex="-1">2. Data we process and why <a class="header-anchor" href="#_2-data-we-process-and-why" aria-label="Permalink to &quot;2. Data we process and why&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Data</th><th>How we store it</th><th>Purpose</th></tr></thead><tbody><tr><td>Email and password</td><td>Managed by Firebase Authentication (Google); we only keep an account identifier</td><td>Create and protect your account</td></tr><tr><td>Acceptance of the terms and of contributing contacts</td><td>Date and version of the accepted text</td><td>Prove your authorization</td></tr><tr><td>Phone numbers looked up or reported</td><td>Only as a code (hash) with a secret key; never the number</td><td>Identify calls and detect spam</td></tr><tr><td>Names and spam labels</td><td>Encrypted with a key derived from each number</td><td>Show who is calling</td></tr><tr><td>Address book (only if you choose to contribute)</td><td>Numbers as codes and encrypted names; personal names (&quot;Mom&quot;) are discarded</td><td>Identify calls for the community</td></tr></tbody></table><p>We do <strong>not</strong> use the data for advertising, do <strong>not</strong> sell it and do <strong>not</strong> build profiles.</p><h2 id="_3-data-about-people-without-an-account" tabindex="-1">3. Data about people without an account <a class="header-anchor" href="#_3-data-about-people-without-an-account" aria-label="Permalink to &quot;3. Data about people without an account&quot;">​</a></h2><p>When a user contributes their address book, data about third parties (numbers and names) is processed. To reduce the impact on them:</p><ul><li>Phone numbers are never stored, only codes.</li><li>A name is only shown if at least 3 different people saved it the same way.</li><li>There is no search by name: a name is only seen by someone who already has the number.</li><li>Anyone can ask us to hide the names of their number, without an account (<a href="/Tranqui/en/guia/apelacion">how</a>).</li></ul><h2 id="_4-your-rights" tabindex="-1">4. Your rights <a class="header-anchor" href="#_4-your-rights" aria-label="Permalink to &quot;4. Your rights&quot;">​</a></h2><p>You can access, update, correct and delete your data, request proof of your authorization, be informed about how your data is used, revoke your authorization and file complaints with the Superintendence of Industry and Commerce (SIC).</p><p>From the app you can see what data we keep, stop contributing your address book and delete your account.</p><h2 id="_5-inquiries-and-complaints" tabindex="-1">5. Inquiries and complaints <a class="header-anchor" href="#_5-inquiries-and-complaints" aria-label="Permalink to &quot;5. Inquiries and complaints&quot;">​</a></h2><p>Write to <span class="placeholder">[CONTACT EMAIL]</span>.</p><ul><li><strong>Inquiries:</strong> answered within 10 business days.</li><li><strong>Complaints:</strong> answered within 15 business days.</li></ul><h2 id="_6-security" tabindex="-1">6. Security <a class="header-anchor" href="#_6-security" aria-label="Permalink to &quot;6. Security&quot;">​</a></h2><p>We use encrypted connections (HTTPS), keyed codes for numbers, name encryption, per-user lookup limits against mass data extraction, and logs that contain no numbers or names.</p><h2 id="_7-international-transfer" tabindex="-1">7. International transfer <a class="header-anchor" href="#_7-international-transfer" aria-label="Permalink to &quot;7. International transfer&quot;">​</a></h2><p>Authentication is provided by Firebase (Google) and servers may be outside Colombia, in countries with an adequate level of data protection. <span class="placeholder">[SERVER LOCATION]</span></p><h2 id="_8-validity" tabindex="-1">8. Validity <a class="header-anchor" href="#_8-validity" aria-label="Permalink to &quot;8. Validity&quot;">​</a></h2><p>This policy applies from its publication. If it changes, we will publish the new version here and ask you to accept it in the app.</p>',24)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
